// Generated by `mdbook-mermaid install docs/book`, then PATCHED LOCALLY.
//
// mdbook-mermaid 0.17.0 wires its theme-change listeners to bare element ids
// ("coal", "ayu", ...), but mdbook 0.5.x renamed the theme buttons to
// "mdbook-theme-coal" etc. getElementById then returned null and this file threw
// `Cannot read properties of null (reading 'addEventListener')` on EVERY page.
// The throw came after mermaid.initialize(), so diagrams still drew — but the
// console carried an error everywhere and switching theme no longer re-rendered
// them in the new palette.
//
// themeButton() below tries the current id, then the legacy one, and skips the
// listener when neither exists. Re-running `mdbook-mermaid install` will
// overwrite this file and reintroduce the bug — re-apply the patch, or drop it
// once upstream supports mdbook 0.5.x.

(() => {
    const darkThemes = ['ayu', 'navy', 'coal'];
    const lightThemes = ['light', 'rust'];

    const classList = document.getElementsByTagName('html')[0].classList;

    let lastThemeWasLight = true;
    for (const cssClass of classList) {
        if (darkThemes.includes(cssClass)) {
            lastThemeWasLight = false;
            break;
        }
    }

    const theme = lastThemeWasLight ? 'default' : 'dark';
    mermaid.initialize({ startOnLoad: true, theme });

    // mdbook 0.5.x ids are "mdbook-theme-<name>"; older versions used "<name>".
    const themeButton = (name) =>
        document.getElementById(`mdbook-theme-${name}`) || document.getElementById(name);

    // Simplest way to make mermaid re-render the diagrams in the new theme is via refreshing the page

    for (const darkTheme of darkThemes) {
        themeButton(darkTheme)?.addEventListener('click', () => {
            if (lastThemeWasLight) {
                window.location.reload();
            }
        });
    }

    for (const lightTheme of lightThemes) {
        themeButton(lightTheme)?.addEventListener('click', () => {
            if (!lastThemeWasLight) {
                window.location.reload();
            }
        });
    }
})();
